Part 1 — Supabase Migration: Analysis Storage
Apply via Supabase MCP (project ref: `zhaarabzemhantyxxckq`).

```sql
-- Stores one analysis record per user per week
CREATE TABLE IF NOT EXISTS journal_analysis (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  analysis_week DATE NOT NULL, -- Monday of the week being analyzed (DATE type)

  -- Theme tracking
  themes JSONB NOT NULL DEFAULT '[]',
  -- Array of: { theme: string, count: int, sources: ['journal'|'cabinet'], 
  --             firstSeen: date, weeksSeen: int }

  -- Cross-source gaps
  journal_only_themes JSONB DEFAULT '[]',  -- themes in journal, not Cabinet
  cabinet_only_themes JSONB DEFAULT '[]',  -- themes in Cabinet, not journal

  -- The insight text delivered to the user
  insight_text TEXT NOT NULL,

  -- RAG passages that grounded the insight
  grounding_passages JSONB DEFAULT '[]',
  -- Array of: { author: string, work: string, chunk_text: string, relevance: string }

  -- Longitudinal data
  weeks_analyzed INT NOT NULL DEFAULT 1,
  dominant_theme TEXT, -- the single most persistent theme this week

  -- Distress flag — queued for human review before delivery
  distress_flagged BOOLEAN NOT NULL DEFAULT FALSE,
  distress_notes TEXT,

  -- Delivery tracking
  delivered BOOLEAN NOT NULL DEFAULT FALSE,
  delivered_at TIMESTAMPTZ,

  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  UNIQUE(user_id, analysis_week)
);

CREATE INDEX IF NOT EXISTS idx_journal_analysis_user_id
  ON journal_analysis(user_id);

CREATE INDEX IF NOT EXISTS idx_journal_analysis_week
  ON journal_analysis(analysis_week);

CREATE INDEX IF NOT EXISTS idx_journal_analysis_distress
  ON journal_analysis(distress_flagged)
  WHERE distress_flagged = TRUE;

-- RLS: users can only read their own analysis
ALTER TABLE journal_analysis ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can read their own analysis"
  ON journal_analysis FOR SELECT
  USING (user_id = auth.uid());

-- Service role handles all writes (bypasses RLS)

```

