2b. Fetch journal entries for a user

```javascript
async function getUserJournalEntries(userId, dayCount = 7) {
  const since = new Date(Date.now() - dayCount * 24 * 60 * 60 * 1000).toISOString();
  const { data } = await supabase
    .from('journal_entries') // adjust
    .select('content, created_at, entry_type') // adjust column names
    .eq('user_id', userId)
    .gte('created_at', since)
    .order('created_at', { ascending: true });
  return data || [];
}

```

2c. Fetch Cabinet conversations for a user

```javascript
async function getUserCabinetConversations(userId, dayCount = 7) {
  const since = new Date(Date.now() - dayCount * 24 * 60 * 60 * 1000).toISOString();

  // Fetch conversations updated in the window
  const { data: convos } = await supabase
    .from('cabinet_conversations')
    .select('*')
    .eq('user_id', userId)
    .gte('updated_at', since)
    .order('updated_at', { ascending: true });

  if (!convos || convos.length === 0) return [];

  // Extract user messages only (not counselor responses)
  // The messages are stored as a jsonb array — adjust extraction
  // to match actual schema found in Part 0
  const userMessages = [];
  for (const convo of convos) {
    const messages = convo.messages || []; // adjust field name
    const userTurns = messages
      .filter(m => m.role === 'user')
      .map(m => ({ content: m.content, created_at: convo.updated_at }));
    userMessages.push(...userTurns);
  }
  return userMessages;
}

```

Important: Also extract counselor responses that generated meaningful philosophical exchange — not just user messages. The counselor's response to a topic confirms the topic was substantive enough to engage. Include a sample of notable counselor responses where they directly addressed a user's struggle.
2d. Fetch longitudinal context

```javascript
async function getLongitudinalContext(userId) {
  const { data } = await supabase
    .from('journal_analysis')
    .select('analysis_week, themes, dominant_theme, insight_text')
    .eq('user_id', userId)
