4a. New Railway endpoint for fetching insights
Add to `server/index.js`:
GET `/api/user/insight`
JWT-authenticated. Returns the most recent undelivered (or most recent overall) insight for the authenticated user:

```javascript
app.get('/api/user/insight', async (req, res) => {
  const userId = await getAuthenticatedUserId(req);
  if (!userId) return res.status(401).json({ error: 'Unauthorized' });

  const { data } = await supabase
    .from('journal_analysis')
    .select('*')
    .eq('user_id', userId)
    .eq('distress_flagged', false) // never surface distress-flagged insights automatically
    .order('analysis_week', { ascending: false })
    .limit(1)
    .single();

  if (!data) return res.json({ insight: null });

  // Mark as delivered if not already
  if (!data.delivered) {
    await supabase
      .from('journal_analysis')
      .update({ delivered: true, delivered_at: new Date().toISOString() })
      .eq('id', data.id);
  }

  res.json({ insight: data });
});

```

